INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи овардани об ба ҷанговарҳо</h2><p>Овардани об ба ҷанговарҳо (Furrow Irrigation) яке аз қадимитарин ва ҳанӯз бештар истифодашаванда усулҳои овардани об дар ҷаҳон аст, ки асосан дар кӯпорҳои сатҳӣ аз қабили ҷӯ, ҷаҳонӣ, гандум ва олода истифода мешавад. Дар ин усул, об тавассути чангҳо ё ҷанговарҳои хурду дароз дар тӯли сатҳҳои кӯпорӣ равона шуда, тадриҷан ба решаҳои растанӣ табобат меёбад. Гарчанде ин усул нисбат ба овардани оби қатқораӣ ё боронӣ содатар ва арзонтар аст, аммо барои таъмини самаранокии баландтарин ба дониши дақиқи техникӣ дар соҳаҳои заминшиносӣ, хокшиносӣ ва гирӯмехи ҳисоб мекунад. Мақсади ин дастурамали муфассал муҳокими ҷанбаҳои гуногуни овардани об ба ҷанговарҳо аз нигоҳи тарҳрезии каналҳои лӯлавӣ, шуруби поёнӣ ва заминамояндагӣ аст, то ки деҳқонҳо метавонанд аз оби истифодашудаи худ ҳадди аксар таъсирро бар решаҳои растанӣ ба даст оварда, натиҷаи бештаре дошта бошанд.</p><p>Сарфшавии энергия барои интиқоли об дар ин система камтар аз системаҳои фишори баланд аст, аммо мусоидати асосӣ тақсимоти баробари об дар тамоми дарозии чанг мебошад. Ғайрибаробарии овардани об метавонад ба камбудии намӣ дар як қисм ва дар чанг ғарқшудан дар қисми дигар оварда расонад, ки бевосита ба самаранокии маҳсулот таъсир мерасонад. Бинобар ин, дониши амиқ дар бораи тағйирёбии ҷараёни об дар ҷанговарҳо қадами аввал барои идоракунии муваффақи ин система аст.</p>\n\n<h2>Принсипҳои фаннӣ ва гирӯмехи овардани об ба ҷанговарҳо</h2><h3>Тарҳрезии шурӯрӣ ва пҳлои чангҳо</h3><p>Муҳимтарин параметр дар тарҳрезии дурусти овардани об ба ҷанговарҳо, шурӯри замин аст. Заминҳои даштӣ (камшурӯрӣ) то 1 то 3 фоиз шароити беҳтаринро барои эҷоди ҷараёни ором ва баробар фароҳам меорад. Агар шурӯри бештар бошад, ҷараёни об тезтар шуда, боиси таркиш хушкӣ ва табобати ғайрибаробар мешавад; дар навбат, шурӯри бехосе аз ҳисоб ва анҷоми ҷараёни об ва ҷамъомадӣро ба вуҷуд меорад. Пҳлои чангҳо низ бояд дар асоси диаметри лӯлавҳои интиқоли об ва фосилаи сатҳҳои кӯпор саморасозӣ шавад, то ки суръати ҷараёни мувофиқ нигоҳ дошта шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-آبیاری-رانشی-تصویر-شاخص.webp" alt="راهنمای جامع آبیاری رانشی - تصویر 1"/><figcaption>Овардани об ба ҷанговарҳо дастурамали муфассал</figcaption></figure><h3>Нақши нобаробарии хок</h3><p>Навъи хоккаш муайянкунаандаи асосии вақти обёрӣ дар системаи шинҷии (рашӣ) мебошад. Дар хокҳои ғаҳвор ва сабук суръати ҷозибиши об хеле баланд аст ва бинобар ин, вақти воридшавии об ба шинаро бояд кӯтоҳ бошад ва давомнокии обёрӣ баланд бошад, то пеш аз ҷозибиши пурра тамоми шинар намнок шавад. Баръакс, дар хокҳои глисти ва вазнин ҷозибиш хеле оҳиста аст ва дар сурати идомаи ҷараён эҳтимоли обравшавӣ вуҷуд дорад. Омодагии намуди хоккати кишоварзӣ барои танзими дараҷаи обёрӣ ҳаётӣ аст. Барои мушкилот беш оид ба интихоби бирчини мувофиқ бо шароити хок, шумо метавонед ба роҳнамои <a href="https://navar-abyari.ir/miqdori-tukhmi-chuchqa-da-gektar/">Ҳаҷми хушкаи ғаллодор дар гектар</a> чун мисол ба куштҳои гуногун муроҷиат кунед.</p>\n\n<h2>Муфодаҳо ва нопарҳезҳои усули шинҷии (рашӣ)</h2><p>Обёрӣ бо усули шинҷӣ аз ҳамаи усулҳое мебошад, ки хароҷоти сармояи ибтидоӣ дар тасаввури паст дорад ва ба таҷҳизоти мураккаб лозим надорад. Ин хосият онро барои қисми калони кишоварзони дорои буҷети маҳдуд ҷозиб мегардонад. Инчунин, ин усул аз сабаби баръакашидани фишори кам ба системаҳои интиқоли об, барои киштзорҳое, ки ба манбаъҳои оби сатҳии муносиб дуроӣ доранд, мувофиқ аст. Вале ин усул ду камоирии асосӣ дорад: аввалан, коэффитсиенти таваккалнакӯнии тақсимоти об дар шинарҳои дароз аст, ки боиси харобшавии об дар охирҳои шинар мегардад. Доввум, ин усул боиси пайдоиши ноустувори дар сифати расонидани об ба решаҳо дар марҳалаҳои ҳассоси рӯзшӯрӣ мегардад.</p><h3>Таҳлили иқтисодӣ ва самаранокии истеҳсоки</h3><p>Барои беҳтар намудани вазъи иқтисодӣ ва самаранокии истеҳсоки дар киштзорҳое, ки обёрӣ бо усули шинҷӣ доранд, идоракунии дақиқи вақти обёрӣ зарур аст. Харобшавии обҳои зиёд дар шинарҳо метавонад боиси афзоиши хароҷотҳои энергияи насоскуӣ ва хароҷотҳои ҷамъоварии об шавад. Дар ин роҳ, истифодаи техникаҳои кам кардани зарароварӣ ва идоракунии ошнои манбаъҳои обӣ зарур аст. Кишоварзон метавонанд бо омӯзиш <a href="https://navar-abyari.ir/arzan-hosildori-gektar-rahnemo/">Арзонтарин истеҳсоки гектар реҳном</a> (Дар ин ҷо мақсад самараноки беҳтарин истифодаи захираҳо дар зиркӯрҳои мушаххас аст) идеяҳои барои ҳадафнок намудани таъмини маблағҳои амалиётӣ барои ҷамъоварии обро пайдо кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-آبیاری-رانشی-کاربرد-عملی.webp" alt="راهنمای جامع آبیاری رانشی - تصویر 2"/><figcaption>Системаи обёрӣи каналӣ: Раҳнамоиаш</figcaption></figure><h2>Нуктаҳои амалӣ дар ороиш ва иҷрои дуруст</h2><ol><li><strong>Омода кардани замина:</strong> Мизон кардани замин бо эҳтиёт пеш аз кушодани каналҳо, то дар ҷойҳои мушаххас об ҷамъ нашавад.</li><li><strong>Истифодаи лӯлаҳои тақсимотӣ:</strong> Ба ҷои каналҳои дастикушода, лӯлаҳои ПВХ ё нӯраҳои тақсимотӣ истифода баред, то истеҳсоли об дар оғози каналҳоро дақиқтар идора кунед.</li><li><strong>Ҷадвали вақти обёрӣ:</strong> Баробории дар сатҳҳои хунки рӯз (субҳ ҷо-бозҳо ё шом) барои кам кардани бозшавии сатҳи об тавсия дода мешавад.</li><li><strong>Нигардории чуқурии дохили шудан:</strong> Истифодаи созиномахҳои хок (сайкометр) барои назорат кардани чуқурии дохили шудани об ба решаҳо.</li></ol><p>Яке аз мушкилоти маъмул дар иҷрои баробории лағиш, бориш аз атрофи ҷарукҳо аст, ки ба хушкшавии растаниҳо дар наздикии ҷарукҳо оварда мерасонад. Барои ғалаба кардан ба ин мушкилӣ, метавон аз техникаҳои карди муназзам ё истифодаи пӯшидани растаниҳо барои кам кардани бозшавӣ байни ҷарукҳо истифода бард. Дар ин ҳолат, омӯзиш <a href="https://navar-abyari.ir/corn-seed-rate-per-hectare/">Шумораи ғаллаи гурудҳо дар гектар</a> комакрасанда аст, зеро масоҳати карди ғаллаи гурудҳо бевосита ба масоҳати ҷарукҳо ва ниёз ба оби онҳо дар системаи лағиш таъсир мерасонад.</p>\n\n<h2>Муқоиса бо усулҳои нав интисоби об</h2><p>Агарчӣ баробории лағиш асосан васеъ аст, аммо усулҳои навтар, ба монанди баробории бо тарқоти (Drip Tape) барои баъзе маҳсулот, бо сабаби тақсимоти баробартар ва кам кардани бозшавӣ, ивазкунии беҳтар ҳисоб карда мешаванд. Баробории бо тарқоти имкониятҳои назорати дақиқтари тарраркӣ-ниҳо дар зонаи решаҳоро фароҳам меорад. Барои ошно гардидан ба ҳадди масоҳати мувофиқи пайдарпаии тарқоти дар карди ғаллаҳо, санҷиш <a href="https://navar-abyari.ir/wheat-drip-tape-spacing-irrigation-methods/">Фавосоядории рӯи тиби ва усулҳои обёрӣи гулак</a> Тавсия дода мешавад. Гарчанде ки ин усулҳои навбунёд маъмулӣ, гарчанде ки арзиши баландтар доранд, аммо дар муҳлати дарозмуддат бо кам кардани истифодаи об ва зиёд шудани ҳосил, аз усули ронӣ бартар ҳисоб мешаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-آبیاری-رانشی-جزئیات-فنی.webp" alt="راهنمای جامع آبیاری رانشی - تصویر 3"/><figcaption>Обёрӣи ронии comprehensive guide</figcaption></figure><p>Интихоби байни обёрӣи ронӣ ва усулҳои навбунёд, вобаста ба омилҳое мисли намуди меҳвари, шароитҳои иқлими ва буҷаи деҳқофон аст. Дар минтаҳое, ки камбуди об зиёд бошад ва шароитҳои иқлимӣ хушк бошад, гузашт ба системҳои обёрӣи дақиқтар зарурӣ мешавад.</p><h2>Саволҳои зудпуршуда (FAQ)</h2><ul><li><strong>Обёрӣи ронӣ барои кадом меҳвара мувофиқ аст?</strong><br>Ин усул барои коробиҳои сатҳҳовии бо қаторҳои дароз мисли арпа, гулак, зурат ва баъзе отлаҳо мувофиқ аст. Барои меҳвараҳои руудишаванда ё ҳиссноки бодаби мисли писта ва бодам, ин усул идеалӣ нест.</li><li><strong>Чӣ гуна метавон аз зиёфати об дар обёрӣи ронӣ кам кард?</strong><br>Истифодаи сангҳои чорчӯбаро барои идоракунии ҷараён, кунҳи ҷунбони бехҳо ба муайян кардани шуби оптималӣ ва оборӣ кардан дар соатҳои хунуки рӯз аз муҳимтарин усулҳо ба ҳисоб мераванд.</li><li><strong>Оё оборӣ бо ҷараён бо нӯри дупеҳо илтиҳом мекунад?</strong><br>Бале, дар баъзе дунбобҳои шурӯъшуда, бо истифода аз каналҳои муштарики об барои обори нӯри дупаҳо истифода мешавед, то ниёз ба системаи помпаи фишори баланд аз байн шавад.</li></ul><h2>Хулоса ва натиҷа</h2><p>Оборӣ бо ҷараён як усули иқтисодӣ ва барқароршавии оборӣ аст, ки дар ҳолати иҷрои дуруст ва бо назардошти шароитҳои хокӣ ва иқлимоӣ метавонад самаранокии мувофиқ дошта бошад. Калиди муваффақият, дарки дурусти динамикаи ҷараёни об ва идоракунии дақиқи тартиб додани вақти оборӣ мебошад. Кирдорони деҳқони бояд бо омӯзиши классикӣ бо усулҳои нав аз ҷумла, истифода аз ҳавозаҳои намдорӣ ва пагоҳҳои обиву ҳавоӣ ба идоракунии дӯстдошташаданӣ барои манбаъҳои оби худ таваҷҷӯҳ кунанд. Дар охир, интихоби системаи мувофиқи оборӣ, қарорест, ки бевосита ба уфуқомонивӣ ва барқароршавии деҳки шумо таъсир мерасонад. Барои маълумот дар бораи тафсилоти бештар дар бораи фосилаҳо ва тарҳҳои гуногун, шумо метавонед ба <a href="https://navar-abyari.ir/nuqtahoi-muhim-pesh-az-nasbi-leantai-tip-dar-maydon/">Нуқтаҳои муҳим пеш аз насб кардани нӯри дупаҳо ба дунбо</a> намоён кунед то диди мукаммалтареро дошта бошед, ки имкониятҳои мавҷудаи дӯстдошташаванд.</p>','Равишно номаи умумӣ барои суръатнокӣ ғизои зироатҳои дон ва ошхӯр','Обориши раванӣ яке аз усулҳои бештар истифодашаванда дар кишоварзӣи муосир аст, ки барои тар кардани хок аз ҷараёни идорашавандаи об истифода мебарад. Дар ин мақолаи васеъ, ҳама чизро дар бораи принсипҳои тарроҳӣ, иҷрои дуруст ва идоракунии беҳтарини ин системаи обориши меомӯзед.','publish','closed','closed','ravysh-no-mayi-umumiy-suryatnoki-gizoyi-ziroati-don-oshkhur',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
